// The sounds feature's graph-platform surface (#4215, epic #3604) — the modules a graph-loaded Sounds
// imports but does NOT redraw: the pure sound domain (descriptors, the kit graph, the kit catalogue, the
// synth) and the kit hook. Registered HERE, inside the feature, because the shell must not reach a
// feature's internals (#1545). The sounds host calls this at module load, before the graph page loads.
//
// The split is the usual one at a smaller scale: the graph carries the LAYOUT (rail, inspector, kit
// canvas), and everything that makes a noise or derives a graph stays code.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as SoundDescriptor from "@/features/sounds/lib/soundDescriptor";
import * as SoundGraph from "@/features/sounds/lib/soundGraph";
import * as SoundKits from "@/features/sounds/lib/soundKits";
import * as Synth from "@/features/sounds/lib/synth";
import * as UseSoundKits from "@/features/sounds/useSoundKits";
import * as GraphPlatform from "@/features/sounds/graphPlatform";

/** Register the Sounds page's injected graph-platform modules by the specifiers it imports.
 *
 *  Idempotent, and holding NO MODULE STATE on purpose. `registerAppModule` is a Map set, so calling
 *  this twice writes the same entries twice and changes nothing — the `done` flag this used to carry
 *  saved Map writes, it never guarded correctness. It had to go: `bsc graph impl set` refuses a
 *  `provides` from a stateful record onto a REGISTERED specifier, because the record wins over the
 *  registry and would vendor a second copy of that state to every graph consumer.
 */
export function registerSoundsPlatform(): void {
  registerAppModule("@/features/sounds/lib/soundDescriptor", SoundDescriptor);
  registerAppModule("@/features/sounds/lib/soundGraph", SoundGraph);
  registerAppModule("@/features/sounds/lib/soundKits", SoundKits);
  registerAppModule("@/features/sounds/lib/synth", Synth);
  registerAppModule("@/features/sounds/useSoundKits", UseSoundKits);
  registerAppModule("@/features/sounds/graphPlatform", GraphPlatform);
}
